# Collect 1-star reviews (3 pages each) + score/count/distribution
import json, time
doms = ["nordvpn.com","expressvpn.com","surfshark.com","protonvpn.com","cyberghostvpn.com","privateinternetaccess.com","ipvanish.com","mullvad.net"]
out = {}
for d in doms:
    revs=[]; meta=None
    for p in (1,2,3):
        goto_url(f"https://www.trustpilot.com/review/{d}?stars=1&page={p}")
        wait_for_load(); time.sleep(2)
        r = js("""(() => {
          const t=document.body.innerText;
          const arts=[...document.querySelectorAll('article')].filter(a=>{const i=a.querySelector('img[alt*="Rated"]');return i&&i.alt.startsWith('Rated 1 ')}).map(a=>{
            const h=a.querySelector('h2'); const b=a.querySelector('[data-service-review-text-typography]');
            return (h?h.innerText:'')+' :: '+(b?b.innerText:'').replace(/\\s+/g,' ').slice(0,500)});
          const m=t.match(/Reviews\\s+([\\d,]+)\\s*•\\s*([\\d.]+)/);
          const dist=t.match(/1-star\\s*([\\d<.]+%?)/);
          const k=t.indexOf('Reviews');
          return {arts, m: m?[m[1],m[2]]:null, dist: dist?dist[0]:null, head:t.slice(t.indexOf('Reviews'),t.indexOf('Reviews')+80)};
        })()""")
        if p==1: meta=r
        revs+=r['arts']
    out[d]={'meta':meta,'revs':revs}
    print(d, meta['m'], meta['dist'], len(revs), repr(meta['head'][:60]))
json.dump(out, open('~/.hermes/profiles/voyagerbrowser/cache/scratch/tp2.json','w'))

